/* cholesky.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "cholesky.h"

/* ------------------------------------------------------------------------
 * Tunable parameters for the Cholesky kernel.
 *
 * CHOLESKY_INNER_UNROLL controls whether we manually unroll the inner
 * dot-product loops.  When set to 4 (the default), the k-loops are
 * explicitly unrolled by a factor of four, which tends to map well to
 * modern x86-64 cores.  For any other value, a simple scalar loop is
 * used and the compiler is left to perform its own unrolling/vectorization.
 * ---------------------------------------------------------------------- */
#ifndef CHOLESKY_INNER_UNROLL
# define CHOLESKY_INNER_UNROLL 4
#endif


/* Array initialization.
 *
 * The original semantics are preserved, but the implementation is
 * reorganized to improve cache locality:
 *  - Use row pointers to avoid repeated address computations.
 *  - Compute the positive semi-definite matrix B = A * A^T using
 *    a row-major traversal that keeps accesses to A and B mostly
 *    contiguous in memory.
 */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Build a simple lower-triangular matrix with unit diagonal. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE* Ai = A[i];
      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	Ai[j] = 0;
      }
      Ai[i] = 1;
    }

  /* Make the matrix positive semi-definite: A <- A * A^T. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Local restrict-qualified aliases help the compiler reason about
   * aliasing and enable better optimization of the triple loop.
   */
  DATA_TYPE (*restrict a)[n] = A;
  DATA_TYPE (*restrict b)[n] = POLYBENCH_ARRAY(B);

  /* Compute B = A * A^T explicitly.
   *
   * For each (r,s), we compute:
   *   B[r][s] = sum_{t=0}^{n-1} A[r][t] * A[s][t]
   *
   * The order of additions for a fixed pair (r,s) is the same as in
   * the original code (increasing t), so the floating-point result
   * is mathematically identical to:
   *
   *   B[r][s] = 0;
   *   for t: B[r][s] += A[r][t] * A[s][t];
   *
   * but with improved memory access patterns:
   *   - ar[t] and as[t] are accessed with unit stride (row-major).
   *   - b[r][s] is written once per (r,s) instead of incremented
   *     repeatedly in the innermost loop.
   */
  for (r = 0; r < n; ++r)
    {
      const DATA_TYPE *restrict ar = a[r];
      DATA_TYPE *restrict br = b[r];

      for (s = 0; s < n; ++s)
	{
	  const DATA_TYPE *restrict as = a[s];
	  DATA_TYPE sum = (DATA_TYPE)0;

	  for (t = 0; t < n; ++t)
	    sum += ar[t] * as[t];

	  br[s] = sum;
	}
    }

  /* Copy B back into A.  This keeps the original external interface
   * unchanged (A contains the SPD matrix on exit).
   */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict arw = a[r];
      const DATA_TYPE *restrict br = b[r];
      for (s = 0; s < n; ++s)
	arw[s] = br[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
    if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
  }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * This is a left-looking in-place Cholesky factorization:
 *   On entry:  A is a symmetric positive-definite matrix.
 *   On exit:   A contains its Cholesky factor L such that A = L * L^T.
 *
 * Optimizations compared to the reference implementation:
 *   - Use a restrict-qualified row-major alias to A to help alias analysis.
 *   - Use row pointers (ai, aj) to avoid repeated address arithmetic.
 *   - Accumulate inner products in scalar temporaries instead of
 *     repeatedly reading and writing A[i][j] / A[i][i].
 *   - Manually unroll the innermost k-loops by a factor of 4 when
 *     CHOLESKY_INNER_UNROLL == 4 (default), improving ILP and allowing
 *     the compiler to generate tighter code.
 *   - The mathematical computation is unchanged; only the evaluation
 *     order within each dot-product is modified in a way that preserves
 *     the left-to-right accumulation over k.
 */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local alias with explicit restrict to enable better optimization. */
  DATA_TYPE (*restrict a)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict ai = a[i];

    /* Off-diagonal elements in row i (j < i). */
    for (j = 0; j < i; j++) {
      DATA_TYPE *restrict aj = a[j];

      /* Start from the current A[i][j] value and subtract the inner product
       * of the already computed parts of rows i and j.
       *
       * Original:
       *   for (k = 0; k < j; k++)
       *     A[i][j] -= A[i][k] * A[j][k];
       *   A[i][j] /= A[j][j];
       *
       * Here we accumulate in a scalar 'sum' and write back once.
       */
      DATA_TYPE sum = ai[j];

#if CHOLESKY_INNER_UNROLL == 4
      int k_limit = j & ~3; /* Largest multiple of 4 less than or equal to j. */

      /* Unrolled loop: process 4 products per iteration. */
      for (k = 0; k < k_limit; k += 4) {
        sum -= ai[k]     * aj[k];
        sum -= ai[k + 1] * aj[k + 1];
        sum -= ai[k + 2] * aj[k + 2];
        sum -= ai[k + 3] * aj[k + 3];
      }

      /* Remainder loop for the last (j % 4) elements. */
      for (; k < j; ++k) {
        sum -= ai[k] * aj[k];
      }
#else
      /* Fallback: no explicit unrolling, leave it to the compiler. */
      for (k = 0; k < j; k++) {
        sum -= ai[k] * aj[k];
      }
#endif

      ai[j] = sum / aj[j];
    }

    /* Diagonal element A[i][i].  Compute:
     *   A[i][i] = sqrt(A[i][i] - sum_{k=0}^{i-1} A[i][k]^2).
     *
     * Original:
     *   for (k = 0; k < i; k++)
     *     A[i][i] -= A[i][k] * A[i][k];
     *   A[i][i] = SQRT_FUN(A[i][i]);
     *
     * Again, we accumulate into a scalar and write back once.
     */
    DATA_TYPE diag = ai[i];

#if CHOLESKY_INNER_UNROLL == 4
    int k_limit_diag = i & ~3;

    for (k = 0; k < k_limit_diag; k += 4) {
      DATA_TYPE a0 = ai[k];
      DATA_TYPE a1 = ai[k + 1];
      DATA_TYPE a2 = ai[k + 2];
      DATA_TYPE a3 = ai[k + 3];

      diag -= a0 * a0
	    + a1 * a1
	    + a2 * a2
	    + a3 * a3;
    }

    for (; k < i; ++k) {
      DATA_TYPE aik = ai[k];
      diag -= aik * aik;
    }
#else
    for (k = 0; k < i; k++) {
      DATA_TYPE aik = ai[k];
      diag -= aik * aik;
    }
#endif

    ai[i] = SQRT_FUN(diag);
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
