static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Use a restrict-qualified pointer for the whole function to
     enable better optimization while avoiding aliasing. */
  DATA_TYPE (*restrict A_)[n] = A;

  /* Initial lower-triangular matrix with 1s on the diagonal. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A_[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A_[i][j] = 0;
      }
      A_[i][i] = 1;
    }

  /* Make the matrix positive semi-definite by computing
     B = A * A^T.

     The original version:
       1) Initialized B to zero.
       2) For each t, updated every B[r][s] with
          B[r][s] += A[r][t] * A[s][t].

     That repeatedly touched every element of B for each t, leading
     to poor cache locality and many memory reads/writes.

     Optimized version below:
       - We compute one element B[r][s] at a time as a dot product
         of row r and row s of A.
       - The inner loop over t accesses A row-wise (contiguous).
       - Each B[r][s] is accumulated entirely in a local scalar and
         written back exactly once.
       - The order of accumulation for each B[r][s] is still
         increasing in t, preserving the original numerical behavior
         w.r.t. the reduction order. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict Br = B_[r];
      const DATA_TYPE *Ar = A_[r];

      for (s = 0; s < n; ++s)
        {
          const DATA_TYPE *As = A_[s];
          DATA_TYPE sum = (DATA_TYPE)0;

          /* Dot product of rows r and s of A. */
          #pragma GCC ivdep
          for (t = 0; t < n; ++t)
            sum += Ar[t] * As[t];

          Br[s] = sum;
        }
    }

  /* Copy B back into A (row-wise) */
  for (r = 0; r < n; ++r)
    {
      memcpy(A_[r], B_[r], (size_t)n * sizeof(DATA_TYPE));
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
    if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
  }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky [[gnu::flatten, gnu::noinline]] (int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Use a restrict-qualified pointer to the matrix to help the
     compiler with alias analysis within this kernel. */
  DATA_TYPE (*restrict A_)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
     /* Pointer to row i improves locality and reduces address
        arithmetic in inner loops. */
     DATA_TYPE *restrict Ai = A_[i];

     /* j < i: compute the strictly lower-triangular entries in row i. */
     for (j = 0; j < i; j++) {
        DATA_TYPE *restrict Aj = A_[j];

        /* Original code:
             for (k = 0; k < j; k++)
                A[i][j] -= A[i][k] * A[j][k];
             A[i][j] /= A[j][j];

           This is equivalent to:
             A[i][j] = (A[i][j] - sum_{k<j} A[i][k]*A[j][k]) / A[j][j];

           We compute the dot product explicitly into 'sum' to keep
           A[i][j] in a register and to make the inner loop a clean
           vectorizable reduction. */
        DATA_TYPE sum = (DATA_TYPE)0;

        #pragma GCC ivdep
        for (k = 0; k < j; k++) {
           sum += Ai[k] * Aj[k];
        }

        Ai[j] = (Ai[j] - sum) / Aj[j];
     }

     /* i == j case: update the diagonal entry A[i][i]. */

     /* Original code:
          for (k = 0; k < i; k++)
             A[i][i] -= A[i][k] * A[i][k];
          A[i][i] = SQRT_FUN(A[i][i]);

        which equals:
          A[i][i] = sqrt(A[i][i] - sum_{k<i} A[i][k]^2);

        Again we express it as an explicit reduction. */
     DATA_TYPE diag_sum = (DATA_TYPE)0;

     #pragma GCC ivdep
     for (k = 0; k < i; k++) {
        DATA_TYPE aik = Ai[k];
        diag_sum += aik * aik;
     }

     Ai[i] = SQRT_FUN(Ai[i] - diag_sum);
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
