# define INIT_BLOCK_S 32
#endif

/* --------------------------------------------------------------------
 * Array initialization.
 * ------------------------------------------------------------------*/
static
void init_array(int n,
                DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Local "restrict" view of A to help the compiler with alias analysis. */
  DATA_TYPE (*restrict A_)[n] = A;

  /* Precompute 1/n once to avoid repeated integer modulus and division. */
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  /* Initialize A to a lower-triangular matrix, as in the original code.
     The expression (-j % n) is equal to -j for 0 <= j < n, so
       (DATA_TYPE)(-j % n) / n + 1
     is mathematically     1 - j / n.
     We use this equivalent, but cheaper, formulation. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Ai = A_[i];

      for (j = 0; j <= i; j++)
        Ai[j] = (DATA_TYPE)1.0 - ((DATA_TYPE)j) * inv_n;

      for (j = i + 1; j < n; j++)
        Ai[j] = (DATA_TYPE)0.0;

      Ai[i] = (DATA_TYPE)1.0;
    }

  /* Make the matrix positive semi-definite: B = A * A^T, then A = B.
     We apply simple blocking in the (r,s) space while keeping the 't'
     loop outermost so that the accumulation order for each B[r][s]
     (over t) is exactly the same as in the original code. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Explicit zero-initialization of B. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict Br = B_[r];
      for (s = 0; s < n; ++s)
        Br[s] = (DATA_TYPE)0.0;
    }

  /* Blocked computation of B[r][s] += A[r][t] * A[s][t]. */
  for (t = 0; t < n; ++t)
    {
      for (int rb = 0; rb < n; rb += INIT_BLOCK_R)
        {
          int r_end = rb + INIT_BLOCK_R;
          if (r_end > n)
            r_end = n;

          for (int sb = 0; sb < n; sb += INIT_BLOCK_S)
            {
              int s_end = sb + INIT_BLOCK_S;
              if (s_end > n)
                s_end = n;

              for (r = rb; r < r_end; ++r)
                {
                  const DATA_TYPE Art = A_[r][t];
                  DATA_TYPE *restrict Br = &B_[r][sb];

                  for (s = sb; s < s_end; ++s)
