static
__attribute__((optimize("unroll-loops")))
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
                     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local "restrict" view for better alias analysis and cache locality. */
  DATA_TYPE (*restrict A_)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      /* Row pointer for current i. */
      DATA_TYPE *restrict Ai = A_[i];

      /* Off-diagonal elements: j < i. */
      for (j = 0; j < i; j++)
        {
          DATA_TYPE *restrict Aj = A_[j];

          /* Accumulate into a scalar temporary to avoid repeated
             loads/stores of Ai[j]. This preserves the exact update
             order of the original loop:
               Ai[j] = Ai[j] - sum_{k < j} Ai[k] * Aj[k]; */
          DATA_TYPE sum = Ai[j];

          /* Inner product over k. Using a simple loop here ensures
             that the subtraction order (k = 0..j-1) is unchanged. */
          for (k = 0; k < j; k++)
            sum -= Ai[k] * Aj[k];

          Ai[j] = sum / Aj[j];
        }

      /* Diagonal element: i == j case. */
      DATA_TYPE sum_diag = Ai[i];

      /* Same idea: accumulate into a scalar with identical k-order. */
      for (k = 0; k < i; k++)
        {
          DATA_TYPE aik = Ai[k];
          sum_diag -= aik * aik;
        }

      Ai[i] = SQRT_FUN(sum_diag);
