#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "cholesky.h"

/* Tunable unrolling factor for the inner-product loops in the
 * Cholesky factorization. 4 is a good default for modern x86_64
 * machines (it maps well to typical SIMD widths), but this can
 * be overridden at compile time, e.g.:
 *
 *   -DCHOLESKY_INNER_UNROLL=1   (disable manual unrolling)
 *   -DCHOLESKY_INNER_UNROLL=4   (default)
 *
 * The code below has a specialized path for 4 and falls back
 * to a simple scalar loop otherwise.
 */
#ifndef CHOLESKY_INNER_UNROLL
# define CHOLESKY_INNER_UNROLL 4
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Initial lower-triangular matrix with unit diagonal,
     identical to the original version. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++)
	A[i][j] = 0;
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite: A <- A * A^T.
   *
   * Original code:
   *   1. B = 0
   *   2. for t: for r: for s: B[r][s] += A[r][t] * A[s][t];
   *   3. A = B
   *
   * Here we compute the same result more efficiently by:
   *   - computing each B[r][s] directly from a local reduction,
   *   - exploiting symmetry (only compute r >= s and mirror),
   *   - keeping the reduction order over t identical for each
   *     element B[r][s] (t = 0..n-1), preserving numerical
   *     semantics for each entry.
   */
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  int r, s, t;
  for (r = 0; r < n; ++r)
    {
      for (s = 0; s <= r; ++s)
	{
	  DATA_TYPE sum = (DATA_TYPE)0;
	  /* Inner-product of row r and row s of A.
	     The t-loop is innermost so that the operations that
	     contribute to each (r,s) element are performed in
	     the same t-order as in the original code. */
	  for (t = 0; t < n; ++t)
	    sum += A[r][t] * A[s][t];

	  (POLYBENCH_ARRAY(B))[r][s] = sum;
	  (POLYBENCH_ARRAY(B))[s][r] = sum; /* exploit symmetry */
	}
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A[r][s] = (POLYBENCH_ARRAY(B))[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky[[gnu::flatten, gnu::noinline]](int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
     /* Work on row i of A. Using a row pointer reduces index
        arithmetic and helps the compiler keep the row in registers. */
     DATA_TYPE *Ai = A[i];

     /* Off-diagonal elements in row i (j < i). */
     for (j = 0; j < i; j++) {
        DATA_TYPE *Aj = A[j];  /* row j, used repeatedly */
        DATA_TYPE sum = Ai[j];
        int k_local = 0;

        /* Dot product:
           sum -= Ai[k] * Aj[k]  for k = 0..j-1.
           We manually unroll by 4 when CHOLESKY_INNER_UNROLL == 4.
           The operations on 'sum' are kept in the same logical
           order as the original scalar loop; only the loop control
           is changed. */
#if CHOLESKY_INNER_UNROLL == 4
        {
          int limit = j & ~3; /* largest multiple of 4 <= j */
          for (; k_local < limit; k_local += 4) {
            sum -= Ai[k_local]     * Aj[k_local];
            sum -= Ai[k_local + 1] * Aj[k_local + 1];
            sum -= Ai[k_local + 2] * Aj[k_local + 2];
            sum -= Ai[k_local + 3] * Aj[k_local + 3];
          }
        }
#endif
        /* Remainder loop (also used when unrolling is disabled). */
        for (; k_local < j; ++k_local) {
          sum -= Ai[k_local] * Aj[k_local];
        }

        Ai[j] = sum / Aj[j];
     }

     /* Diagonal element A[i][i]. */
     {
       DATA_TYPE sum = Ai[i];
       int k_local = 0;

       /* sum -= Ai[k] * Ai[k]  for k = 0..i-1, with optional
          unrolling as above. */
#if CHOLESKY_INNER_UNROLL == 4
       {
         int limit = i & ~3;
         for (; k_local < limit; k_local += 4) {
           sum -= Ai[k_local]     * Ai[k_local];
           sum -= Ai[k_local + 1] * Ai[k_local + 1];
           sum -= Ai[k_local + 2] * Ai[k_local + 2];
           sum -= Ai[k_local + 3] * Ai[k_local + 3];
         }
       }
#endif
       for (; k_local < i; ++k_local) {
         sum -= Ai[k_local] * Ai[k_local];
       }

       Ai[i] = SQRT_FUN(sum);
     }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_cholesky (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
